        n = len(isConnected)
        visited = set()
        ans = 0

        for i in range(n):
            if i in visited:
                continue

            ans += 1
            dq = deque([i])
            visited.add(i)

            while dq:
                city = dq.popleft()

                for j in range(n):
                    if isConnected[city][j] == 1 and j not in visited:
                        visited.add(j)
                        dq.append(j)

        return ans

