class Solution:
    def eventualSafeNodes(self, graph: List[List[int]]) -> List[int]:
        reverse_graph = []
        for _ in graph:
            reverse_graph.append([])
        degree = list(map(len, graph))
        for node, next_nodes in enumerate(graph):
            for next_node in next_nodes:
                reverse_graph[next_node].append(node)
        dq = deque((i for i, d in enumerate(degree) if d == 0))
        safe = [False] * len(graph)
        while dq:
            node = dq.popleft()
            safe[node] = True
            for next_node in reverse_graph[node]:
                degree[next_node] -= 1
                if degree[next_node] == 0:
                    dq.append(next_node)
        return [i for i, ok in enumerate(safe) if ok]

