class Solution:
    def eventualSafeNodes(self, graph: List[List[int]]) -> List[int]:
        state = [0] * len(graph)

        def visit(node):
            if state[node]:
                return state[node] == 2
            state[node] = 1
            if not all((visit(next_node) for next_node in graph[node])):
                return False
            state[node] = 2
            return True
        return [node for node in range(len(graph)) if visit(node)]

