class Solution:
    def eventualSafeNodes(self, graph: List[List[int]]) -> List[int]:

        # 시작점에서 연결된 정점을 모두 찾습니다.
        def traverse(neighbors, start):
            # 이미 발견한 정점을 저장합니다.
            visited = {start}
            stack = [start]
            while stack:
                node = stack.pop()
                for next_node in neighbors[node]:
                    if next_node not in visited:
                        visited.add(next_node)
                        stack.append(next_node)
            return visited
        result = []
        for root in range(len(graph)):
            reach = traverse(graph, root)
            degree = {node: 0 for node in reach}
            for node in reach:
                for next_node in graph[node]:
                    degree[next_node] += 1
            dq = deque((node for node in reach if degree[node] == 0))
            count = 0
            while dq:
                node = dq.popleft()
                count += 1
                for next_node in graph[node]:
                    degree[next_node] -= 1
                    if degree[next_node] == 0:
                        dq.append(next_node)
            if count == len(reach):
                result.append(root)
        return result

