class Solution:
    def canVisitAllRooms(self, rooms: List[List[int]]) -> bool:
        # 이미 발견한 정점을 저장합니다.
        visited = {0}
        stack = [0]

        while stack:
            room = stack.pop()

            for key in rooms[room]:
                if key in visited:
                    continue
                visited.add(key)
                stack.append(key)

        return len(visited) == len(rooms)

