class Solution:
    def shortestAlternatingPaths(self, n: int, redEdges: List[List[int]], blueEdges: List[List[int]]) -> List[int]:
        neighbors = []
        for _ in range(2):
            neighbors.append([[] for _ in range(n)])
        for color, edges in enumerate([redEdges, blueEdges]):
            for node, next_node in edges:
                neighbors[color][node].append(next_node)
        distance = []
        for _ in range(n):
            distance.append([float('inf')] * 2)
        distance[0] = [0, 0]
        for _ in range(2 * n):
            changed = False
            for node in range(n):
                for color in range(2):
                    for next_node in neighbors[1 - color][node]:
                        if distance[node][color] + 1 < distance[next_node][1 - color]:
                            distance[next_node][1 - color] = distance[node][color] + 1
                            changed = True
            if not changed:
                break
        return [-1 if min(d) == float('inf') else min(d) for d in distance]

