class Solution:
    def numOfMinutes(self, n: int, headID: int, manager: List[int], informTime: List[int]) -> int:
        children = []
        for _ in range(n):
            children.append([])
        for i, p in enumerate(manager):
            if p >= 0:
                children[p].append(i)
        stack = [(headID, 0)]
        answer = 0
        while stack:
            node, t = stack.pop()
            answer = max(answer, t)
            for next_node in children[node]:
                stack.append((next_node, t + informTime[node]))
        return answer

