class Solution:
    def numOfMinutes(self, n: int, headID: int, manager: List[int], informTime: List[int]) -> int:
        arrival = {headID: 0}
        for i in range(n):
            path = []
            node = i
            while node not in arrival:
                path.append(node)
                node = manager[node]
            while path:
                next_node = path.pop()
                p = manager[next_node]
                arrival[next_node] = arrival[p] + informTime[p]
        return max(arrival.values())

