        neighbors = []
        for _ in range(n):
            neighbors.append([])
        for node, next_node in connections:
            neighbors[node].append((next_node, 1))
            neighbors[next_node].append((node, 0))
        stack = [0]
        # 이미 발견한 정점을 저장합니다.
        visited = {0}
        answer = 0
        while stack:
            node = stack.pop()
            for next_node, cost in neighbors[node]:
                if next_node not in visited:
                    visited.add(next_node)
                    answer += cost
                    stack.append(next_node)
        return answer

