class Solution:
    def minReorder(self, n: int, connections: List[List[int]]) -> int:
        neighbors = []
        for _ in range(n):
            neighbors.append([])
        for node, next_node in connections:
            neighbors[node].append((next_node, 1))
            neighbors[next_node].append((node, 0))
        # 처음에는 각 정점이 자기 묶음의 대표입니다.
        parent = [-1] * n
        parent[0] = 0
        order = [0]
        for node in order:
            for next_node, _ in neighbors[node]:
                if parent[next_node] == -1:
                    parent[next_node] = node
                    order.append(next_node)
        return sum((parent[next_node] == node for node, next_node in connections))

