class Solution:
    def criticalConnections(self, n: int, connections: List[List[int]]) -> List[List[int]]:
        adj = []
        for _ in range(n):
            adj.append([])
        for node, next_node in connections:
            adj[node].append(next_node)
            adj[next_node].append(node)
        discovery = [-1] * n
        low = [0] * n
        # 처음에는 각 정점이 자기 묶음의 대표입니다.
        parent = [-1] * n
        discovery[0] = low[0] = 0
        clock = 1
        stack = [(0, iter(adj[0]))]
        result = []
        while stack:
            node, neighbors = stack[-1]
            next_node = next(neighbors, None)
            if next_node is None:
                stack.pop()
                p = parent[node]
                if p != -1:
                    low[p] = min(low[p], low[node])
                    if low[node] > discovery[p]:
                        result.append([p, node])
            elif next_node != parent[node]:
                if discovery[next_node] == -1:
                    parent[next_node] = node
                    discovery[next_node] = low[next_node] = clock
                    clock += 1
                    stack.append((next_node, iter(adj[next_node])))
                else:
                    low[node] = min(low[node], discovery[next_node])
        return result

