class Solution:
    def criticalConnections(self, n: int, connections: List[List[int]]) -> List[List[int]]:
        neighbors = []
        for _ in range(n):
            neighbors.append([])
        for node, next_node in connections:
            neighbors[node].append(next_node)
            neighbors[next_node].append(node)
        discovery = [-1] * n
        low = [0] * n
        timer = 0
        result = []

        def visit(node, parent):
            nonlocal timer
            discovery[node] = low[node] = timer
            timer += 1
            for next_node in neighbors[node]:
                if next_node == parent:
                    continue
                if discovery[next_node] == -1:
                    visit(next_node, node)
                    low[node] = min(low[node], low[next_node])
                    if low[next_node] > discovery[node]:
                        result.append([node, next_node])
                else:
                    low[node] = min(low[node], discovery[next_node])
        visit(0, -1)
        return result

