class Solution:
    def criticalConnections(self, n: int, connections: List[List[int]]) -> List[List[int]]:
        result = []
        for skip, edge in enumerate(connections):
            # 처음에는 각 정점이 자기 묶음의 대표입니다.
            parent = list(range(n))
            # 작은 묶음을 큰 묶음에 붙이기 위한 크기입니다.
            size = [1] * n

            # 같은 묶음인지 비교할 대표를 찾습니다.
            def find(node):
                while node != parent[node]:
                    parent[node] = parent[parent[node]]
                    node = parent[node]
                return node

            # 서로 다른 묶음일 때만 합칩니다.
            def union(first, second):
                first = find(first)
                second = find(second)
                if first == second:
                    return False
                if size[first] < size[second]:
                    first, second = (second, first)
                parent[second] = first
                size[first] += size[second]
                return True
            for i, (u, next_node) in enumerate(connections):
                if i != skip:
                    union(u, next_node)
            if len({find(i) for i in range(n)}) > 1:
                result.append(edge)
        return result

