class Solution:
    def nearestExit(self, maze: List[List[str]], entrance: List[int]) -> int:
        m, n = (len(maze), len(maze[0]))
        start = tuple(entrance)

        # 조건을 만족하는 다음 후보를 만듭니다.
        def neighbors(node):
            r, c = node
            return [(a, b) for a, b in [(r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)] if 0 <= a < m and 0 <= b < n and (maze[a][b] == '.')]

        def exit(node):
            return node != start and (node[0] in (0, m - 1) or node[1] in (0, n - 1))
        sources = [start]
        dq = deque(((0, node) for node in sources))
        # 이미 발견한 정점을 저장합니다.
        visited = set(sources)
        while dq:
            distance, node = dq.popleft()
            if exit(node):
                return distance
            for next_node in neighbors(node):
                if next_node not in visited:
                    visited.add(next_node)
                    dq.append((distance + 1, next_node))
        return -1

