class Solution:
    def shortestBridge(self, grid: List[List[int]]) -> int:

        def islands(grid):
            n = len(grid)
            groups = []
            # 이미 발견한 정점을 저장합니다.
            visited = set()
            for r in range(n):
                for c in range(n):
                    if not grid[r][c] or (r, c) in visited:
                        continue
                    group = {(r, c)}
                    visited.add((r, c))
                    stack = [(r, c)]
                    while stack:
                        a, b = stack.pop()
                        for x, y in [(a + 1, b), (a - 1, b), (a, b + 1), (a, b - 1)]:
                            if 0 <= x < n and 0 <= y < n and grid[x][y] and ((x, y) not in visited):
                                visited.add((x, y))
                                group.add((x, y))
                                stack.append((x, y))
                    groups.append(group)
            return groups
        first, second = islands(grid)
        n = len(grid)
        dq = deque(((r, c, 0) for r, c in first))
        visited = set(first)
        while dq:
            r, c, d = dq.popleft()
            for a, b in [(r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)]:
                if 0 <= a < n and 0 <= b < n and ((a, b) not in visited):
                    if (a, b) in second:
                        return d
                    visited.add((a, b))
                    dq.append((a, b, d + 1))

