    def shortestBridge(self, grid: List[List[int]]) -> int:

        def islands(grid):
            n = len(grid)
            groups = []
            # 이미 발견한 정점을 저장합니다.
            visited = set()
            for r in range(n):
                for c in range(n):
                    if not grid[r][c] or (r, c) in visited:
                        continue
                    group = {(r, c)}
