                    stack = [(r, c)]
                    while stack:
                        a, b = stack.pop()
                        for x, y in [(a + 1, b), (a - 1, b), (a, b + 1), (a, b - 1)]:
                            if 0 <= x < n and 0 <= y < n and grid[x][y] and ((x, y) not in visited):
                                visited.add((x, y))
                                group.add((x, y))
                                stack.append((x, y))
                    groups.append(group)
            return groups
        first, second = islands(grid)
        n = len(grid)
        distance = []
        for r in range(n):
            distance.append([0 if (r, c) in first else float('inf') for c in range(n)])
        for r in range(n):
            for c in range(n):
                if r:
                    distance[r][c] = min(distance[r][c], distance[r - 1][c] + 1)
                if c:
                    distance[r][c] = min(distance[r][c], distance[r][c - 1] + 1)
        for r in range(n - 1, -1, -1):
            for c in range(n - 1, -1, -1):
                if r + 1 < n:
                    distance[r][c] = min(distance[r][c], distance[r + 1][c] + 1)
                if c + 1 < n:
                    distance[r][c] = min(distance[r][c], distance[r][c + 1] + 1)
        return min((distance[r][c] for r, c in second)) - 1

