class Solution:
    def accountsMerge(self, accounts: List[List[str]]) -> List[List[str]]:
        owner = {}
        # 처음에는 각 정점이 자기 묶음의 대표입니다.
        parent = list(range(len(accounts)))
        # 작은 묶음을 큰 묶음에 붙이기 위한 크기입니다.
        size = [1] * len(accounts)

        # 같은 묶음인지 비교할 대표를 찾습니다.
        def find(node):
            while node != parent[node]:
                parent[node] = parent[parent[node]]
                node = parent[node]
            return node

        # 서로 다른 묶음일 때만 합칩니다.
        def union(first, second):
            first = find(first)
            second = find(second)
            if first == second:
                return False
            if size[first] < size[second]:
                first, second = (second, first)
            parent[second] = first
            size[first] += size[second]
            return True
        for i, account in enumerate(accounts):
            for email in account[1:]:
                if email in owner:
                    union(i, owner[email])
                owner[email] = i
        buckets = defaultdict(list)
        for email, i in owner.items():
            buckets[find(i)].append(email)
        return [[accounts[root][0]] + sorted(emails) for root, emails in buckets.items()]

