class Solution:
    def findCheapestPrice(self, n: int, flights: List[List[int]], src: int, dst: int, k: int) -> int:
        neighbors = []
        for _ in range(n):
            neighbors.append([])
        for node, next_node, c in flights:
            neighbors[node].append((next_node, c))
        best = {(src, 0): 0}
        heap = [(0, src, 0)]
        answer = float('inf')
        while heap:
            cost, node, used = heapq.heappop(heap)
            if cost != best[node, used]:
                continue
            if node == dst:
                answer = cost
                break
            if used == k + 1:
                continue
            for next_node, c in neighbors[node]:
                key = (next_node, used + 1)
                if cost + c < best.get(key, float('inf')):
                    best[key] = cost + c
                    heapq.heappush(heap, (cost + c, next_node, used + 1))
        if answer == float('inf'):
            return -1
        else:
            return answer

