class Solution:
    def findCheapestPrice(self, n: int, flights: List[List[int]], src: int, dst: int, k: int) -> int:
        neighbors = []
        for _ in range(n):
            neighbors.append([])
        for node, next_node, c in flights:
            neighbors[node].append((next_node, c))
        from functools import lru_cache

        @lru_cache(None)
        def solve(node, left):
            if node == dst:
                return 0
            if left == 0:
                return float('inf')
            return min((c + solve(next_node, left - 1) for next_node, c in neighbors[node]), default=float('inf'))
        answer = solve(src, k + 1)
        if answer == float('inf'):
            return -1
        else:
