class Solution:
    def maxProbability(self, n: int, edges: List[List[int]], succProb: List[float], start_node: int, end_node: int) -> float:
        neighbors = []
        for _ in range(n):
            neighbors.append([])
        for (node, next_node), p in zip(edges, succProb):
            neighbors[node].append((next_node, p))
            neighbors[next_node].append((node, p))
        best = [0.0] * n
        best[start_node] = 1.0
        heap = [(-1.0, start_node)]
        while heap:
            negative_probability, node = heapq.heappop(heap)
            value = -negative_probability
            if value < best[node]:
                continue
            if node == end_node:
                return value
            for next_node, p in neighbors[node]:
                if value * p > best[next_node]:
                    best[next_node] = value * p
                    heapq.heappush(heap, (-best[next_node], next_node))
        return best[end_node]

