        cols = len(maze[0])
        start = tuple(start)
        destination = tuple(destination)

        # 한 방향으로 벽이나 경계까지 굴립니다.
        def moves(row, col):
            result = []
            for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                next_row, next_col = row, col
                steps = 0
                while (0 <= next_row + dr < rows and
                       0 <= next_col + dc < cols and
                       maze[next_row + dr][next_col + dc] == 0):
                    next_row += dr
                    next_col += dc
                    steps += 1
                if steps > 0:
                    result.append(((next_row, next_col), steps))
            return result

        distance = {start: 0}
        visited = set()
        while True:
            position = None
            cost = float("inf")
            for candidate in distance:
                if candidate not in visited and distance[candidate] < cost:
                    position = candidate
                    cost = distance[candidate]

            if position is None:
                return -1
            if position == destination:
                return cost
            visited.add(position)

            for next_position, steps in moves(*position):
                new_cost = cost + steps
                if new_cost < distance.get(next_position, float("inf")):
                    distance[next_position] = new_cost

