class Solution:
    def shortestDistance(self, maze: List[List[int]], start: List[int], destination: List[int]) -> int:
        rows = len(maze)
        cols = len(maze[0])
        start = tuple(start)
        destination = tuple(destination)

        # 한 방향으로 벽이나 경계까지 굴립니다.
        def moves(row, col):
            result = []
            for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                next_row, next_col = row, col
                steps = 0
                while (0 <= next_row + dr < rows and
                       0 <= next_col + dc < cols and
                       maze[next_row + dr][next_col + dc] == 0):
                    next_row += dr
                    next_col += dc
                    steps += 1
                if steps > 0:
                    result.append(((next_row, next_col), steps))
            return result

        distance = {start: 0}
        dq = deque([start])
        queued = {start}
        while dq:
            position = dq.popleft()
            queued.remove(position)

            for next_position, steps in moves(*position):
                new_cost = distance[position] + steps
                if new_cost < distance.get(next_position, float("inf")):
                    distance[next_position] = new_cost
                    # 더 짧은 경로를 찾으면 다시 탐색합니다.
                    if next_position not in queued:
                        dq.append(next_position)
                        queued.add(next_position)

        return distance.get(destination, -1)

