class Solution:
    def minCostConnectPoints(self, points: List[List[int]]) -> int:
        n = len(points)
        used = set()
        distance = [float('inf')] * n
        distance[0] = 0
        answer = 0
        for _ in range(n):
            node = min((i for i in range(n) if i not in used), key=lambda i: distance[i])
