        # 특정 간선을 제외하거나 반드시 넣었을 때의 MST 비용입니다.
        def build(skip=-1, force=-1):
            # 처음에는 각 정점이 자기 묶음의 대표입니다.
            parent = list(range(n))
            # 작은 묶음을 큰 묶음에 붙이기 위한 크기입니다.
