                if size[first] < size[second]:
                    first, second = (second, first)
                parent[second] = first
                size[first] += size[second]
                return True
            cost = 0
            count = 0
            if force >= 0:
                u, next_node, w = edges[force]
                union(u, next_node)
                cost += w
                count += 1
            for i in sorted(range(len(edges)), key=lambda i: edges[i][2]):
                if i == skip or i == force:
                    continue
                u, next_node, w = edges[i]
                if union(u, next_node):
