        # 시작점에서 연결된 정점을 모두 찾습니다.
        def traverse(neighbors, start):
            # 이미 발견한 정점을 저장합니다.
            visited = {start}
            stack = [start]
            while stack:
                u = stack.pop()
                for next_node in neighbors[u]:
                    if next_node not in visited:
                        visited.add(next_node)
                        stack.append(next_node)
            return visited

        # 특정 간선을 제외하거나 반드시 넣었을 때의 MST 비용입니다.
