        parent = list(range(n))
        size = [1] * n

        def find(node):
            while node != parent[node]:
                parent[node] = parent[parent[node]]
                node = parent[node]
            return node

        def union(first, second):
            first = find(first)
            second = find(second)
            if first == second:
                return False
            if size[first] < size[second]:
                first, second = (second, first)
            parent[second] = first
            size[first] += size[second]
            return True
        critical = []
        pseudo = []
        byweight = defaultdict(list)
        for i, (u, next_node, w) in enumerate(edges):
            byweight[w].append(i)
        for w, ids in sorted(byweight.items()):
            candidates = []
            for i in ids:
                u, next_node, _ = edges[i]
                a, b = (find(u), find(next_node))
                if a != b:
                    candidates.append((a, b, i))
            for a, b, i in candidates:
                neighbors = defaultdict(list)
                for x, y, j in candidates:
                    if i != j:
                        neighbors[x].append(y)
                        neighbors[y].append(x)
                if b not in traverse(neighbors, a):
                    critical.append(i)
                else:
                    pseudo.append(i)
            for a, b, i in candidates:
