        # 서로 다른 묶음일 때만 합칩니다.
        def union(first, second):
            first = find(first)
            second = find(second)
            if first == second:
                return False
            if size[first] < size[second]:
                first, second = (second, first)
            parent[second] = first
            size[first] += size[second]
            return True
        components = node_count
        total = 0
        while components > 1:
            cheapest = {}
            for u, next_node, w in edges:
                a, b = (find(u), find(next_node))
                if a == b:
                    continue
                for root in (a, b):
                    if root not in cheapest or w < cheapest[root][2]:
                        cheapest[root] = (u, next_node, w)
            if not cheapest:
                return -1
            for u, next_node, w in cheapest.values():
                if union(u, next_node):
                    total += w
                    components -= 1
        return total
